import React, { useState } from "react";
import Garage from "./Components/Garage";

function Car(props) {
  const [color] = useState("red"); 

  return (
    <div>
      <h2>This car is {color} {props.carInfo.model}</h2>
      <Garage size="small" />
    </div>
  );
}

export default Car;
